INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65016, 'spa', 'La comida principal del día, generalmente una cena o banquete formal, que en el ', 'La comida principal del día, generalmente una cena o banquete formal, que en el NT sirve tanto como escenario literal como ocasión de profunda carga teológica. Abarca cenas de hospitalidad cotidiana (Lc 14:12), banquetes reales (Mr 6:21), la Última Cena de Jesús con sus discípulos (Jn 13:2; 1 Co 11:20-21) y la cena apocalíptica de las bodas del Cordero (Ap 19:9, 17). El escenario de la mesa comunitaria conecta la comunión humana con la comunión divina a lo largo de todo el NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65022, 'spa', 'El numero cardinal diez, empleado en tres registros distintos en el Nuevo Testam', 'El numero cardinal diez, empleado en tres registros distintos en el Nuevo Testamento. En las parabolas, estructura relatos de preparacion (diez virgenes, Mt 25:1), mayordomia (diez minas, Lc 19:13) y perseverancia (diez monedas, Lc 15:8). En la narrativa, cuenta grupos: los diez discipulos indignados (Mt 20:24; Mr 10:41), los diez leprosos sanados (Lc 17:12-17). En el simbolismo apocaliptico de Apocalipsis, los diez cuernos del dragon representan diez reyes (Ap 12:3; 17:3, 7, 12, 16), imagen tomada de Daniel 7:7.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65024, 'spa', 'Numero cardinal', 'Juan 11:18 mide la distancia de Betania a Jerusalen como ''unos quince estadios''. Hechos 27:28 registra que los marineros sondearon ''quince brazas'' mientras navegaban en la oscuridad. Galatas 1:18 precisa que Pablo paso ''quince dias'' con Pedro en Jerusalen. En todos los casos, el termino funciona como un simple numeral sin carga simbolica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65025, 'spa', 'Región de diez ciudades', 'Mateo 4:25 menciona que multitudes seguían a Jesús desde la Decápolis. Marcos 5:20 relata que el endemoniado sanado comenzó a proclamar en la Decápolis lo que Jesús había hecho por él. Marcos 7:31 describe a Jesús viajando por la región de la Decápolis. El nombre se conserva en todas las lenguas como topónimo reconocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65026, 'spa', 'Número cardinal catorce', 'El número cardinal catorce. En la genealogía de Mateo (Mt 1:17), estructura las tres épocas de la historia de la salvación en grupos de catorce generaciones cada uno, un número probablemente escogido por su conexión con la gematría del nombre del rey David en hebreo (דּוד = 4+6+4 = 14). Pablo lo usa como marcador temporal: catorce años desde su visión celestial (2 Co 12:2) y catorce años antes de regresar a Jerusalén (Gá 2:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65027, 'spa', 'Diezmo o décima parte', 'Décimo o diezmo, la décima porción entregada como ofrenda o tributo. En Hebreos 7:2-9, los cuatro usos sirven al argumento de que el sacerdocio de Melquisedec supera al de Leví: Abraham pagó diezmos a Melquisedec (He 7:2, 4), y los levitas que recaudan diezmos fueron simbólicamente diezmados a través de su antepasado (He 7:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65028, 'spa', 'Ordinal o fracción', 'Juan 1:39 señala la «hora décima» cuando los discípulos fueron a ver dónde se hospedaba Jesús, aproximadamente las cuatro de la tarde, un detalle que sugiere memoria de testigo ocular. Apocalipsis 11:13 describe «la décima parte de la ciudad» que cayó en el terremoto. Apocalipsis 21:20 enumera el crisopras como la «décima» piedra del cimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65029, 'spa', 'Cobrar o pagar diezmos', 'Ambas ocurrencias aparecen en el argumento de Hebreos 7 sobre la superioridad de Melquisedec. Primero, Melquisedec ''cobró diezmos de'' Abraham (7:6: español ''diezmó,'' alemán ''verzehnten''), estableciendo que el menor da al mayor. Luego, Leví ''ha sido diezmado'' a través de Abraham (7:9: inglés ''has been tithed,'' español ''ha sido diezmado''), mostrando la subordinación del sacerdocio levítico al orden de Melquisedec.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65030, 'spa', 'Aceptable ante Dios', 'Aceptable, grato o agradable, especialmente ante los ojos de Dios. El término aparece en contextos de receptividad divina: el jubilar ''año agradable del Señor'' de Isaías 61 (Lc 4:19), el salvífico ''tiempo aceptable'' de 2 Co 6:2 (citando Is 49:8), y la aceptación por parte de Dios de quienes le temen de toda nación (Hch 10:35). También describe la acogida humana — o su ausencia — en la declaración profética de Jesús en Nazaret (Lc 4:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65031, 'spa', 'Seducir con engaño', 'Santiago 1:14 describe cómo «cada uno es tentado cuando es atraído y seducido por su propio deseo». 2 Pedro 2:14 y 2:18 advierten sobre falsos maestros que «seducen a almas inestables» y atraen a quienes apenas están escapando del error. Los contextos abarcan tanto la tentación personal interna como la seducción externa ejercida por maestros engañosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65032, 'spa', 'Planta leñosa perenne que produce ramas, frutos u hojas, empleada tanto en senti', 'Planta leñosa perenne que produce ramas, frutos u hojas, empleada tanto en sentido literal como metaforico. En la enseñanza sinoptica, el fruto del arbol revela su naturaleza: los arboles buenos dan buen fruto, los malos dan mal fruto (Mt 7:17-19; 12:33; Lc 6:43-44), y el arbol infructuoso enfrenta el hacha (Mt 3:10; Lc 3:9). La semilla de mostaza se convierte en un gran arbol donde anidan las aves (Mt 13:32; Lc 13:19). En Apocalipsis, el ''arbol de la vida'' da doce clases de fruto y sus hojas son ''para la sanidad de las naciones'' (Ap 22:2, 14), completando el arco biblico iniciado en el Eden. Judas 12 usa ''arboles otoñales sin fruto, dos veces muertos, desarraigados'' como imagen vivida de los falsos maestros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65037, 'spa', 'Diestra, lado derecho', 'La mano derecha o el lado derecho, abarcando tanto la referencia corporal literal (Mt 5:29-30) como el asiento teologicamente cargado de autoridad divina. ''A la diestra de Dios'' (Mc 16:19; Hch 2:33; Heb 1:3) se fundamenta en el Sal 110:1 para la exaltacion de Cristo. En Galatas 2:9 significa compañerismo y aprobacion. Un solo concepto confirmado a traves de las 54 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65042, 'spa', 'Orar o elevar súplicas fervientes dirigidas a Dios, buscando intervención o favo', 'Orar o elevar súplicas fervientes dirigidas a Dios, buscando intervención o favor divino. Mateo 9:38 y Lucas 10:2 lo emplean en el mandato de Jesús de ''rogar al Señor de la mies,'' mientras que Hechos 4:31 registra la oración comunitaria. Lucas 22:32, donde Jesús le dice a Pedro ''yo he rogado por ti,'' constituye la instancia más íntima de súplica dirigida a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65043, 'spa', 'Rogar, suplicar o implorar a otra persona con urgencia', 'Rogar, suplicar o implorar a otra persona con urgencia. Lucas 5:12 muestra al leproso postrándose y rogándole a Jesús; Lucas 8:28 presenta al endemoniado suplicándole. El español ''rogar'' y ''te ruego'' captan la urgencia personal y directa. El contexto de interacción cara a cara es claro en las quince ocurrencias de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65060, 'spa', 'Ciudad de Licaonia', 'Hechos 14:6 registra que Pablo y Bernabé huyeron de la persecución hacia «Listra y Derbe, ciudades de Licaonia». Hechos 14:20 narra su partida «al día siguiente a Derbe». Hechos 16:1 menciona que Pablo llegó «a Derbe y luego a Listra». El topónimo se conserva con variaciones mínimas en las distintas lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65062, 'spa', 'Material de cuero', 'Aparece idénticamente en Mateo 3:4 y Marcos 1:6, ambos describiendo el cinturón de cuero de Juan el Bautista como parte de su atuendo profético. El detalle sirve para caracterizar a Juan como una figura similar a Elías que mora en el desierto, con vestimenta apropiada para su estilo de vida ascético y llamado profético. El término identifica directamente la composición material de su cinturón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65063, 'spa', 'Infligir golpes a alguien mediante azotes o flagelación, tanto por violencia inf', 'Infligir golpes a alguien mediante azotes o flagelación, tanto por violencia informal como por castigo judicial oficial. En las parábolas, los siervos enviados a una viña son golpeados por labradores malvados (Mt 21:35; Mr 12:3, 5). En Hechos, los apóstoles son azotados por las autoridades (Hch 5:40; 16:37). Jesús advierte a sus seguidores que deben esperar ese trato en sinagogas y ante concilios (Mr 13:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65076, 'spa', 'Atar o encadenar', 'Mateo 23:4 condena a los líderes religiosos que «atan cargas pesadas» sobre los demás. Lucas 8:29 describe al endemoniado que muchas veces había sido «atado con cadenas y grillos». Hechos 22:4 recoge el testimonio de Pablo de que «ataba y entregaba a la cárcel» tanto a hombres como a mujeres. Los contextos van desde la sujeción física hasta la opresión figurada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65078, 'spa', 'Prisionero, cautivo', 'Prisionero, cautivo: persona retenida en confinamiento o bajo custodia, ya sea en una carcel literal o bajo guardia militar. El termino designa a alguien detenido por autoridad civil o politica. Barrabas es llamado δέσμιος en la Pascua (Mt 27:15-16), y Pablo y Silas son δέσμιοι en Filipos (Hch 16:25, 27). Pablo adopta el titulo voluntariamente en sus epistolas (Ef 3:1; Flm 1:9), reinterpretando el encarcelamiento como marca de servicio fiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65082, 'spa', 'Cadena, grillete, atadura', 'Cadena, grillete, atadura: cadena fisica, grillete o atadura usada para sujetar a un prisionero. Este es el sentido dominante en el NT, cubriendo dieciseis de dieciocho apariciones. Las cartas de Pablo desde la prision convierten estas cadenas literales en un simbolo teologico: sus prisiones autentican su ministerio evangelico (Fil 1:13-14; Col 4:18). El terremoto en Filipos suelta las cadenas de todos los presos (Hch 16:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65084, 'spa', 'Atadura, impedimento', 'Atadura, impedimento: vínculo figurado o impedimento que ata el cuerpo o una facultad de una persona, usado metaforicamente y no en referencia a encarcelamiento literal. En Marcos 7:35, la ''atadura de su lengua'' describe un impedimento del habla que Jesus libera, mientras que en Lucas 13:16 la ''atadura'' de Satanas sobre una mujer encorvada durante dieciocho anos es rota mediante sanidad. Ambos pasajes usan δεσμός para enmarcar la discapacidad como cautiverio que Cristo viene a deshacer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65089, 'spa', 'Guardián de prisión', 'Las tres apariciones se encuentran en Hechos 16:23, 27 y 36, durante el encarcelamiento de Pablo y Silas en Filipos. El carcelero los recibe bajo custodia, casi se quita la vida cuando el terremoto abre la prisión y experimenta una conversión dramática al descubrir que los prisioneros no habían huido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65090, 'spa', 'Cárcel o prisión', 'Lugar de encarcelamiento o reclusión donde los presos son custodiados bajo guardia y en cadenas. La etimología del término (de δεσμός, «cadena, atadura») pone de relieve el aspecto de sujeción física. Las cuatro apariciones neotestamentarias implican custodia física: Juan el Bautista preso por Herodes (Mt 11:2) y los apóstoles encerrados en la cárcel pública de Jerusalén (Hch 5:21, 5:23; 16:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65091, 'spa', 'Prisionero bajo custodia', 'Ambas apariciones están en Hechos 27, narrando el viaje de Pablo a Roma como prisionero: primero cuando los prisioneros son entregados al centurión Julio (27:1), luego cuando los soldados contemplan matar a los prisioneros durante el naufragio para evitar su escape (27:42). El contexto enfatiza su estatus legal como personas bajo custodia en lugar de viajeros libres.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65092, 'spa', 'Amos', 'Amos. Amos humanos, específicamente propietarios de esclavos que ejercen autoridad sobre personas esclavizadas en el hogar. Las Epístolas Pastorales y 1 Pedro usan δεσπότης consistentemente para este rol social: los esclavos deben considerar a sus amos dignos de honor (1 Timoteo 6:1), especialmente a los amos creyentes (1 Timoteo 6:2), y someterse incluso a los severos (1 Pedro 2:18; Tito 2:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65093, 'spa', 'Soberano, Señor', 'Soberano, Señor. Amo soberano: título para Dios o Cristo como gobernante absoluto y dueño de todo, enfatizando una autoridad suprema que no puede ser cuestionada. El cántico de Simeón ''ahora despides a tu siervo, Soberano Señor'' (Lucas 2:29) y la oración de la iglesia ''Soberano Señor, que hiciste el cielo y la tierra'' (Hechos 4:24) emplean δεσπότης donde κύριος solo resultaría insuficiente. Judas 1:4 y 2 Pedro 2:1 advierten contra quienes niegan al único Soberano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65099, 'spa', 'Ven, acércate', 'Interjección imperativa que convoca a acercarse: ''¡Ven!'' Usada por Jesús al llamar a Lázaro del sepulcro (Juan 11:43), al invitar al joven rico al discipulado (Mateo 19:21; Marcos 10:21; Lucas 18:22) y en el mandato de Dios a Abraham (Hechos 7:3). Cada idioma lo traduce con un imperativo de movimiento: español ''¡Ven!'', francés ''viens'', alemán ''komm''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65102, 'spa', 'Hasta ahora', 'Extensión temporal del sentido espacial, que significa ''hasta ahora, hasta el momento presente''. En Romanos 1:13, Pablo escribe que fue impedido ''hasta ahora'' (δεῦρο) de visitar Roma. El español recurre a ''ahora'' y el inglés a ''present'', mostrando el salto semántico del lugar (''acá'') al tiempo (''hasta este punto''), un mapeo metafórico natural hallado en las lenguas indoeuropeas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65103, 'spa', 'Interjección imperativa plural que convoca a un grupo a venir, acercarse, seguir', 'Interjección imperativa plural que convoca a un grupo a venir, acercarse, seguir o presenciar algo. Usada en los llamados de Jesús al discipulado (Mt 4:19; Mr 1:17), su invitación a los cansados (Mt 11:28), la bienvenida escatológica del Rey (Mt 25:34), la convocatoria al banquete de bodas (Mt 22:4) y la invitación del ángel en el sepulcro vacío (Mt 28:6). También aparece en exhortaciones grupales cotidianas (Mr 6:31; Jn 4:29; 21:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65106, 'spa', 'Segundo (ordinal)', 'Segundo (ordinal): El numeral ordinal «segundo» que indica posición en una secuencia o rango, atestiguado 33 veces. Se usa para el segundo mandamiento (Mt 22:39), el segundo ángel o sello en la serie apocalíptica de Apocalipsis (Ap 6:3; 8:8) y eventos narrativos secuenciales (Mr 12:21, el segundo hermano). El español «segundo/segunda», el francés «deuxième» y el alemán «zweite» lo traducen uniformemente como ordinal de posición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65107, 'spa', 'Por segunda vez / de nuevo', 'Por segunda vez / de nuevo: Construcción adverbial que significa «por segunda vez» o «de nuevo», indicando repetición en lugar de orden, hallada 11 veces. El español recurre a «segunda vez», el francés a «seconde fois» y el alemán a «zweites Mal», todos añadiendo un sustantivo explícito de «vez» que el griego deja implícito por contexto. Pasajes teológicamente significativos incluyen Juan 3:4 (Nicodemo: «¿Puede uno entrar por segunda vez en el vientre?»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65114, 'spa', 'Acoger, recibir con hospitalidad', 'Acoger o recibir a una persona con hospitalidad, extendiendo aceptacion y cuidado a quien llega. Este es el sentido caracteristico en los discursos misioneros de Jesus: ''el que os recibe a vosotros, a mi me recibe'' (Mt 10:40). Aparece en contextos de ciudades que reciben a los apostoles (Lc 9:53), Zaqueo acogiendo a Jesus (Lc 19:6) y las primeras iglesias hospedando a misioneros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65115, 'spa', 'Recibir, aceptar', 'Recibir o aceptar algo ofrecido: una ensenanza, mensaje, testimonio o don espiritual. Pablo habla de recibir la palabra con gozo (1 Ts 1:6), y Jesus pregunta si aceptaran la verdad sobre Juan el Bautista (Mt 11:14). El objeto pasa de una persona a una idea o proclamacion, convirtiendo esto en un acto cognitivo y volitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65124, 'spa', 'Tomar en las manos', 'Tomar un objeto fisico en las manos o en posesion propia. En Lucas 16:6-7, el mayordomo dice a los deudores que ''tomen'' sus recibos y los reescriban, un uso concreto y transaccional. Pablo en 2 Corintios 8:17 describe a Tito ''aceptando'' el encargo de recoger fondos. Este es el sentido mas material de δέχομαι, desprovisto de la calidez relacional de la hospitalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65135, 'spa', 'Atar, amarrar físicamente', 'Atar, amarrar físicamente: El sentido físico primario de atar, amarrar o sujetar con cuerdas, cadenas o grilletes. Abarca prisioneros atados en custodia (Mt 14:3; Mr 6:17), animales amarrados a postes (Mt 21:2) y cizaña agrupada en manojos para quemarla (Mt 13:30). Las traducciones recurren uniformemente a verbos concretos de atadura: español «atado», francés «lier», alemán «binden».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65139, 'spa', 'Estar atado (obligación/restricción)', 'Estar atado (obligación/restricción): Extensión figurada que expresa una obligación o restricción vigente, especialmente en las epístolas de Pablo. La esposa «está ligada» a su marido mientras él viva (1 Co 7:39; Ro 7:2), y el propio Pablo «está atado por el Espíritu» (Hch 20:22). El participio perfecto señala un estado permanente, no un evento aislado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65147, 'spa', 'Atar (decreto autoritativo)', 'Atar (decreto autoritativo): Sentido autoritativo, casi jurídico, presente en las declaraciones de Jesús: «todo lo que atéis en la tierra quedará atado en el cielo» (Mt 16:19; 18:18). El modo subjuntivo señala fuerza legislativa. Este sentido también aparece en la imagen parabólica de atar al hombre fuerte antes de saquear su casa (Mt 12:29; Mr 3:27), donde atar representa la victoria sobre una autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65161, 'spa', 'Ciertamente, en verdad', 'Partícula discursiva enfática utilizada para afirmar, intensificar o inyectar urgencia en una declaración, con un matiz temporal-inferencial de «pues bien», «ciertamente» o «en verdad». Los pastores la usan para expresar resolución entusiasta: «Vayamos pues a Belén» (Lc 2:15). La directriz del Espíritu Santo en Hechos 13:2 lleva la fuerza de «Apartadme ahora a Bernabé y a Saulo». Pablo la emplea en la exhortación: «Glorificad, pues, a Dios en vuestro cuerpo» (1 Co 6:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65166, 'spa', 'Claridad evidente', 'El sentido de claridad cognitiva domina el uso neotestamentario. Cada aparición introduce una conclusión que debería ser obvia para cualquier observador razonable: el acento de Pedro revela su identidad, una excepción lógica no requiere declaración explícita y la justificación por la ley contradice la enseñanza clara del profeta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65167, 'spa', 'Dar a conocer, revelar (activa)', 'Dar a conocer, revelar, indicar o significar en voz activa: el sujeto manifiesta, descubre o demuestra algo previamente oculto o confuso. Seis apariciones abarcan revelación profética (1 Pe 1:11, el Espíritu ''indicaba'' los padecimientos de Cristo), significación litúrgica (Heb 9:8), clarificación escatológica (1 Co 3:13) y comunicación fraternal (Col 1:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65169, 'spa', 'Ser mostrado, ser informado (pasiva)', 'Ser mostrado, ser dado a conocer o ser informado en voz pasiva: el sujeto recibe información que otros han comunicado. La única aparición en 1 Co 1:11 es significativa: ''me fue declarado (ἐδηλώθη μοι) por los de Cloé'' que hay contiendas entre los corintios. El cambio a la pasiva subraya que el receptor depende del testimonio ajeno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65174, 'spa', 'Colaborador desertor', 'Colosenses 4:14 incluye a Demas entre quienes envían saludos. Filemón 24 lo nombra entre los «colaboradores» de Pablo. Segunda Timoteo 4:10 registra la dolorosa deserción: «Demas, por amor a este mundo, me ha desamparado». El contraste entre la compañía inicial y el abandono final lo convierte en figura paradigmática de la apostasía por amor a lo temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65176, 'spa', 'Nombre propio dual', 'Hechos 19:24 y 38 describen a Demetrio el platero, fabricante de templecillos de plata de Artemisa, que incitó la oposición al ministerio de Pablo. Tercera Juan 12 elogia a un Demetrio distinto que «ha recibido buen testimonio de todos y de la verdad misma». El contraste entre ambos portadores del nombre subraya que lo decisivo es la fidelidad, no la identidad nominal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65178, 'spa', 'Asamblea cívica popular', 'Asamblea cívica o populacho reunido que actúa como cuerpo colectivo en la esfera pública. En Hechos 12:22, el δῆμος de Cesarea aclama a Herodes a una voz; en Hechos 17:5, una turba es congregada en Tesalónica; y en Hechos 19:30-33, el δῆμος efesio llena el teatro en tumulto. El español «pueblo» refleja el matiz cívico-colectivo más que la mera noción numérica de «multitud».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65179, 'spa', 'Públicamente, en público', 'Público, perteneciente a la esfera cívica; usado adverbialmente (δημοσίᾳ) para expresar ''públicamente, a la vista del pueblo''. Los apóstoles son encarcelados en la prisión pública (Hch 5:18); Pablo denuncia su azotamiento público siendo ciudadano romano (Hch 16:37); Apolos refuta el error en debate abierto (Hch 18:28); y Pablo testifica tanto en público como de casa en casa (Hch 20:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65181, 'spa', 'Denario (moneda romana de plata)', 'Denario (moneda romana de plata): moneda de plata romana (latin denarius), ampliamente usada como moneda corriente y unidad de valor economico en toda Palestina bajo dominio romano. Funciona en las narrativas del NT como medida concreta de salarios diarios (Mt 20:2), deudas (Mt 18:28; Lc 7:41), gasto caritativo (Mr 14:5; Jn 12:5) y costo de provisiones (Mr 6:37; Jn 6:7). El retrato imperial de la moneda tambien da ocasion para la profunda ensenanza de Jesus sobre la autoridad de Dios y la del Cesar (Mt 22:19-21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65185, 'spa', 'a través de/espacial', 'Paso o movimiento a través de un espacio o medio (con genitivo), indicando tránsito espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65192, 'spa', 'por medio de/instrumental', 'Instrumentalidad o medio por el cual se realiza una acción (con genitivo), ''por medio de'', ''mediante''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65193, 'spa', 'por causa de/causal', 'Razón o causa de algo (con acusativo), ''a causa de'', ''debido a'', ''por''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65207, 'spa', 'por amor de', 'Propósito o beneficio de alguien o algo (con acusativo), ''por amor de'', ''en favor de''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65214, 'spa', 'durante/temporal', 'Duración o extensión temporal (con genitivo), ''durante'', ''a lo largo de''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65226, 'spa', 'Travesía o cruce', 'Lucas 16:26 describe el abismo infranqueable: «los que quieran pasar de aquí a vosotros no pueden». Hechos 16:9 registra la visión macedónica: «Pasa a Macedonia y ayúdanos». Hebreos 11:29 recuerda que Israel «atravesó el Mar Rojo como por tierra seca». Los contextos abarcan desde el cruce literal de fronteras geográficas hasta la imposibilidad metafísica de trasponer el abismo entre el Hades y el seno de Abraham.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65228, 'spa', 'Afirmar con confianza', 'Aparece en las epístolas pastorales concerniente a la afirmación confiada: negativamente, de aspirantes a maestros que afirman con certeza cosas que no entienden (1 Timoteo 1:7: español ''afirman con certeza''), y positivamente, cuando se insta a Tito a hablar con confianza sobre las buenas obras (Tito 3:8: español ''afirmes'', alemán ''fest behaupten''). El término enfatiza la fuerte seguridad del hablante sin importar si la afirmación es correcta o no.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65229, 'spa', 'Ver con claridad', 'Mateo 7:5 y Lucas 6:42 usan el término de forma idéntica en la enseñanza sobre la viga y la paja: «entonces verás claramente para sacar la paja del ojo de tu hermano». Marcos 8:25 describe la sanidad en Betsaida: «miró fijamente y fue restaurado y veía todo con claridad». Las traducciones multilingües reflejan uniformemente el concepto de claridad visual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65230, 'spa', 'El diablo, Satanás (nombre propio)', 'El diablo, Satanás (nombre propio): El diablo como ser espiritual personal, adversario supremo de Dios y de la humanidad. Usado como sustantivo propio en los Evangelios, Hechos y las Epístolas, traducido uniformemente como «devil/diablo/Teufel/diable» en lenguas europeas y con términos propios en lenguas asiáticas y del Medio Oriente (hindi शैतान, coreano 마귀, árabe إبليس). Pasajes clave incluyen la narrativa de la tentación (Mt 4:1-11) y la declaración de Jesús sobre su derrota definitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65233, 'spa', 'Calumniador, dado a la acusación maliciosa (adjetivo de personas)', 'Calumniador, dado a la acusación maliciosa (adjetivo de personas): Adjetival: calumniador, dado a la acusación maliciosa contra otros. Restringido a las Epístolas Pastorales (1 Ti 3:11; 2 Ti 3:3; Tit 2:3), donde describe defectos de carácter humano: mujeres que no deben ser «calumniadoras» y personas de los últimos tiempos que serán «calumniadores». El español distingue claramente con «calumniadoras/calumniadores» frente a «diablo» para el nombre propio, confirmando la separación semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65237, 'spa', 'Proclamar públicamente', 'Lucas 9:60 registra el mandato de Jesús: «deja que los muertos entierren a sus muertos, y tú ve y anuncia el reino de Dios». Hechos 21:26 describe a Pablo «dando aviso» del cumplimiento de los días de purificación. Romanos 9:17 cita el Éxodo respecto a Faraón: «para que mi nombre sea proclamado en toda la tierra». En todos los contextos predomina la fuerza de proclamación pública.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65238, 'spa', 'Transcurso del tiempo', 'Marcos 16:1 señala que «habiendo pasado el sábado», las mujeres compraron especias aromáticas. Hechos 25:13 relata que «después de pasados algunos días», Agripa y Berenice llegaron. Hechos 27:9 observa que «habiendo transcurrido mucho tiempo», la navegación era ya peligrosa. En todos los casos se emplea la construcción de genitivo absoluto para marcar transiciones temporales en la narración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65239, 'spa', 'Decisión judicial investigativa', 'Ambos casos ocurren en Hechos durante los procedimientos legales de Pablo: el plan del concilio judío de ''determinar'' el caso de Pablo con mayor precisión (Hechos 23:15: español ''decidiré'', francés ''discerner''), y Félix prometiendo ''decidir'' el asunto cuando llegue más información (Hechos 24:22: inglés ''I will decide''). La evidencia apunta a la investigación y determinación judicial en lugar de la toma de decisiones casual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65240, 'spa', 'Audiencia judicial imperial', 'Proceso formal de audiencia judicial o toma de decisiones imperiales. En Acts 25:21, Pablo apela al César para someterse a la cognitio imperial, término técnico latino para la revisión judicial del emperador. No es una simple decisión, sino un examen exhaustivo con plena autoridad. Las traducciones reconocen el carácter jurídico-técnico de este vocablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65241, 'spa', 'Murmuración desaprobatoria', 'Aparece exclusivamente en el Evangelio de Lucas describiendo los murmullos desaprobatorios de los líderes religiosos sobre la comunión de Jesús con pecadores: los fariseos y escribas murmurando sobre él recibiendo y comiendo con publicanos y pecadores (Lucas 15:2), y la multitud murmurando sobre él hospedándose con Zaqueo (Lucas 19:7). Ambos contextos involucran descontento comunal expresado mediante murmuración en lugar de confrontación directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65242, 'spa', 'Despertar plenamente', 'Despertar completamente del sueño, emergiendo hacia la plena conciencia y lucidez. En el monte de la transfiguración (Luke 9:32), los discípulos vencen su somnolencia y alcanzan vigilia total para contemplar la gloria de Cristo. El término enfatiza la transición de la pesadez del sueño a la percepción completa, no un mero abrir de ojos sino plena alerta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65243, 'spa', 'Conducir la vida', 'Ambas apariciones conciernen la manera de conducir la vida: el estado deseado de llevar una vida tranquila, pacífica y piadosa (1 Timoteo 2:2: español ''pasemos'', alemán ''verbringen''), y el pasado recordado de vivir en malicia y envidia (Tito 3:3: inglés ''living'', español ''viviendo''). El verbo enfatiza no solo existir sino la calidad y carácter de cómo se está transcurriendo la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65244, 'spa', 'Recibir en sucesión', 'Recibir por sucesión o herencia, tomando posesión de lo transmitido por los predecesores. En Acts 7:45, Josué y quienes entran en Canaán reciben la tierra que la generación de Moisés no pudo alcanzar. La expresión capta tanto la transferencia como el aspecto secuencial: una generación entrega a la siguiente lo que recibió de la promesa divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65245, 'spa', 'Corona de soberanía', 'Las tres apariciones se encuentran en las visiones de conflicto cósmico del Apocalipsis: el dragón con siete diademas sobre sus cabezas (12:3), la bestia del mar con diez diademas (13:1) y Cristo Rey conquistador con muchas diademas (19:12). Las múltiples diademas en cada figura simbolizan la pretensión de dominio absoluto y universal sobre reinos y naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65246, 'spa', 'Distribuir, repartir', 'Distribuir o repartir entre un grupo de destinatarios, dividiendo recursos para que cada uno reciba su porción. El milagro de la alimentación (Jn 6:11) y la iglesia primitiva (Hch 4:35) emplean este verbo para el reparto cuidadoso de provisiones. Jesús manda al rico vender y distribuir a los pobres (Lc 18:22), y los despojos se reparten en Lc 11:22.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65247, 'spa', 'Sucesor en cargo', 'Sucesor en un cargo o posición, quien asume las responsabilidades y la autoridad de su predecesor. Cuando el mandato de Félix como procurador terminó, Porcio Festo llegó como su «sucesor» (Acts 24:27), asumiendo la gobernación y heredando los casos pendientes, como el encarcelamiento de Pablo. El término subraya la sucesión oficial y la transferencia de autoridad entre titulares del cargo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65248, 'spa', 'Ceñirse para servir', 'Juan 13:4-5 narra cómo Jesús dejó sus vestiduras, tomó una toalla y «se la ciñó» antes de lavar los pies de los discípulos, adoptando la postura de un siervo. Juan 21:7 describe a Pedro que, al oír que era el Señor, «se ciñó la ropa exterior» (pues estaba ligero de ropa para trabajar) antes de echarse al mar. El gesto une preparación práctica con profundo simbolismo de servicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65249, 'spa', 'Pacto, acuerdo solemne entre partes', 'Pacto, acuerdo solemne entre partes: Pacto — acuerdo solemne y vinculante, especialmente entre Dios y su pueblo. Esto abarca 31 de las 33 apariciones y recorre todo el arco de la historia salvífica: el pacto de Dios con Abraham (Hch 3:25; 7:8; Gá 3:17), la antigua alianza mediada por Moisés (2 Co 3:14; He 8:9) y el nuevo pacto inaugurado en la Última Cena (Mt 26:28; Mr 14:24; Lc 22:20; 1 Co 11:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65251, 'spa', 'Testamento, última voluntad', 'Testamento, última voluntad: Testamento — disposición legal de bienes que se activa con la muerte del testador. Este sentido propiamente grecorromano aparece únicamente en Hebreos 9:16-17, donde el autor argumenta: «Donde hay testamento, es necesario que se constate la muerte del testador, porque un testamento entra en vigor con la muerte; nunca tiene validez mientras vive quien lo otorgó.» El español «testamento» capta con precisión este matiz jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65252, 'spa', 'Diversidades de dones', 'Las tres apariciones se hallan en 1 Corintios 12:4-6, donde Pablo enseña sobre los dones espirituales: «hay diversidad de dones... diversidad de ministerios... diversidad de operaciones». La triple repetición enfatiza que la obra del Espíritu produce una rica variedad sin romper la unidad del cuerpo de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65253, 'spa', 'Dividir y distribuir', 'Aparece en dos contextos distintos que comparten el concepto de repartir: un padre dividiendo su herencia entre sus hijos (Lucas 15:12: español ''dividió'', alemán ''zuteilen''), y el Espíritu Santo distribuyendo dones espirituales individualmente según su determinación (1 Corintios 12:11: inglés ''distributing'', español ''distribuyendo''). Ambos enfatizan la asignación deliberada entre múltiples destinatarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65254, 'spa', 'Limpiar completamente', 'Ambas instancias aparecen en las descripciones paralelas de Juan el Bautista sobre la obra del que ha de venir (Mateo 3:12, Lucas 3:17), usando la imagen del aventado: él ''limpiará a fondo su era'', recogiendo el trigo pero quemando la paja. Las traducciones (español ''limpiará'', francés ''nettoyer'') enfatizan el aspecto de limpieza, mientras que el contexto agrícola subraya la completitud de la separación y purificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65255, 'spa', 'Refutar públicamente', 'Refutar de manera exhaustiva y pública, demostrando el error mediante argumentación sostenida y pruebas. La actividad de Apolos en Acts 18:28 consistió en una demostración vigorosa y pública de que las objeciones judías contra Jesús carecían de fundamento, empleando argumentos escriturarios para confutar decisivamente a sus oponentes. La voz media sugiere un compromiso personal en este debate teológico público.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65256, 'spa', 'Servir o ministrar', 'Servir o ministrar: Prestar servicio activo, ministrar o atender a alguien en un ámbito práctico o espiritual. El rango abarca desde servir la mesa (Lc 10:40; Jn 12:2) hasta las mujeres que sustentaban a Jesús con sus propios recursos (Mt 27:55; Lc 8:3) y el ministerio angélico tras la tentación en el desierto (Mt 4:11). La autodescripción de Jesús en Mateo 20:28 — «el Hijo del Hombre no vino para ser servido, sino para servir» — eleva este verbo al centro de la ética neotestamentaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65262, 'spa', 'Ser servido o atendido', 'Ser servido o atendido: Voz pasiva: ser receptor del servicio, que otros atiendan las necesidades propias. La misma declaración de Mateo 20:28 y Marcos 10:45 proporciona el contraste — «no para ser servido» — estableciendo que recibir servicio es una categoría legítima, aunque Jesús redefine quién debe recibirlo. En 2 Corintios 3:3 y 8:19-20, Pablo emplea formas pasivas para la colecta que está «siendo administrada», donde el verbo adquiere un matiz organizativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65274, 'spa', 'Ministerio, servicio', 'Ministerio, servicio: Servicio activo rendido a Dios o al prójimo, que abarca la atención práctica y la vocación apostólica. Incluye el servicio de mesa de Marta (Lc 10:40), la distribución diaria que motivó el nombramiento de los Siete (Hch 6:1-4), la ayuda en la hambruna para Jerusalén (Hch 11:29) y el encargo apostólico de Pablo (Ro 11:13; 2 Co 4:1). En 2 Corintios 3-6, Pablo lo desarrolla como una teología del ministerio del nuevo pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65279, 'spa', 'Siervo, ministro o asistente que realiza servicio en nombre de otro', 'Siervo, ministro o asistente que realiza servicio en nombre de otro. Jesús emplea este término para invertir las jerarquías sociales: ''el que quiera ser grande entre vosotros será vuestro servidor'' (Mt 20:26; Mr 10:43). Pablo se llama a sí mismo y a sus colaboradores διάκονοι de Cristo (2 Co 3:6; Col 1:7). Los siervos del rey en la parábola del banquete de bodas (Mt 22:13) y las autoridades civiles como servidores de Dios (Ro 13:4) amplían aún más el rango semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65281, 'spa', 'Sentido técnico eclesiástico', 'Sentido técnico eclesiástico: el cargo formal de diácono en la iglesia. Este uso aparece exclusivamente en 1 Ti 3:8 y 3:12, donde se establecen requisitos morales y domésticos específicos para quienes ocupan el cargo. El español marca esta distinción con el latinismo ''diácono'' en lugar del genérico ''servidor,'' señalando el paso del servicio general al rol institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65287, 'spa', 'Doscientos', 'El número cardinal doscientos, empleado como adjetivo cuantitativo para indicar una cuenta de 200. En el NT cuantifica denarios como suma insuficiente para alimentar a una multitud (Marcos 6:37; Juan 6:7), mide la distancia desde la orilla en codos (Juan 21:8) y cuenta soldados en una escolta romana (Hechos 23:23). Cada lengua lo traduce con su equivalente numérico simple.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65288, 'spa', 'Audiencia judicial completa', 'Dar una audiencia judicial exhaustiva y completa, examinando un caso desde todos los ángulos. La promesa del tribuno romano en Hechos 23:35 asegura a Pablo el debido proceso: no un desestimamiento superficial, sino una audiencia plena de cargos y defensa. El tiempo futuro enfatiza el examen formal venidero. Las traducciones reconocen consistentemente el sentido técnico-legal de indagación judicial completa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65289, 'spa', 'Dudar o vacilar', 'Dudar o vacilar: dudar, vacilar o estar dividido internamente, la fractura interior de quien no puede decidirse a creer. Jesus dice a los discipulos que si no dudan (διακριθῆτε) pueden mover montanas (Mt 21:21; Mr 11:23), y Pablo celebra a Abraham que no vacilo (διεκρίθη) en incredulidad (Ro 4:20). El Espiritu le dice a Pedro que vaya con los mensajeros ''sin dudar nada'' (Hch 10:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65290, 'spa', 'Discernir o evaluar', 'Discernir o evaluar: discernir, evaluar o juzgar cuidadosamente, aplicando valoracion critica para determinar la verdad, calidad o conveniencia de algo. Pablo pregunta a los corintios si no hay entre ellos ningun sabio capaz de ''juzgar'' (διακρῖναι) entre hermanos (1 Co 6:5), y los exhorta a ''discernir'' (διακρίνοντες) el cuerpo en la Cena del Senor (1 Co 11:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65292, 'spa', 'Distinguir o diferenciar', 'Distinguir o diferenciar: distinguir o diferenciar entre personas o categorias, haciendo una separacion que reconoce diferencias reales o, negativamente, muestra parcialidad. En Hechos 15:9 Dios ''no hizo distincion'' (διέκρινεν) entre judios y gentiles al dar el Espiritu Santo a ambos, mientras que Santiago 2:4 acusa a quienes muestran favoritismo de haber ''hecho distinciones'' entre ellos mismos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65294, 'spa', 'Contender o disputar', 'Contender o disputar: contender o disputar verbalmente con alguien, la metafora de separacion extendida a la confrontacion adversarial. En Hechos 11:2 el partido de la circuncision ''contendía'' (διεκρίνοντο) con Pedro por su visita a los gentiles, y en Judas 9 el arcangel Miguel, ''al disputar'' (διακρινόμενος) con el diablo sobre el cuerpo de Moises, defirió a la reprension del Senor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65307, 'spa', 'Discernimiento y juicio', 'Romanos 14:1 advierte contra recibir al débil en la fe «para contender sobre opiniones». En 1 Corintios 12:10 se enumera entre los dones el «discernimiento de espíritus». Hebreos 5:14 describe a los maduros que «por la práctica tienen los sentidos ejercitados para discernir el bien y el mal». El término abarca desde la percepción espiritual hasta la controversia doctrinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65308, 'spa', 'Impedir activamente', 'Prevenir o impedir activamente a alguien que lleve a cabo una acción. El intento de Juan el Bautista de impedir el bautismo de Jesús (Mt 3:14) representa una objeción respetuosa pero firme: trató de obstruir lo que le parecía inapropiado. El tiempo imperfecto sugiere una prevención continuada o intentada, finalmente infructuosa, ya que Jesús insistió y Juan cedió.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65309, 'spa', 'Discusión comunitaria', 'Aparece en el Evangelio de Lucas para la discusión comunitaria de eventos significativos: las noticias sobre Zacarías y Elisabet siendo ''discutidas'' por toda la región montañosa (Lucas 1:65: español ''se hablaba'', francés ''se répandre''), y los discípulos ''discutiendo entre ellos'' después de la controvertida sanidad de Jesús en sábado (Lucas 6:11: inglés ''were discussing''). Ambos enfatizan la conversación propagándose a través o dentro de un grupo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65310, 'spa', 'Razonar, discutir o argumentar mediante intercambio verbal, especialmente discur', 'Razonar, discutir o argumentar mediante intercambio verbal, especialmente discurso persuasivo en un entorno público. Es el uso paulino característico: razonar en sinagogas (Hch 17:2; 18:4, 19), disputar con oponentes (Hch 17:17) o debatir entre discípulos (Mr 9:34). Conserva el carácter dialógico del intercambio de ideas y la argumentación basada en las Escrituras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65313, 'spa', 'Hablar, dirigirse, exhortar a alguien con franqueza y autoridad, sin el intercam', 'Hablar, dirigirse, exhortar a alguien con franqueza y autoridad, sin el intercambio implícito del debate. En Hebreos 12:5, la exhortación de Proverbios 3:11-12 ''habla'' (διαλέγεται) a los lectores como a hijos. Aquí el énfasis recae en la interpelación personal más que en el intercambio. El sentido pasa de ''discutir'' a ''dirigir la palabra'' con tono autoritativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65318, 'spa', 'Cesar o interrumpir', 'Cesar o interrumpir una acción, dejando un vacío temporal. En Lucas 7:45, Jesús contrasta la omisión del fariseo con la devoción continua de la mujer: ella ''no cesó'' (οὐ διέλιπεν) de besar sus pies desde el momento en que entró. El aoristo negado expresa continuidad ininterrumpida: ningún intervalo, ninguna cesación en su expresión de amor y arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65319, 'spa', 'Lengua, dialecto', 'Un idioma o dialecto regional específico — el habla distintiva de un pueblo o grupo étnico determinado. Se usa exclusivamente en Hechos para señalar la identidad lingüística de hablantes y oyentes. En Pentecostés cada persona oye a los apóstoles ''en su propio dialecto'' (Hch 2:6, 8), subrayando la precisión lingüística personal del milagro. Pablo se dirige estratégicamente a la multitud de Jerusalén ''en lengua hebrea'' (Hch 21:40; 22:2; 26:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65320, 'spa', 'Reconciliarse mutuamente', 'Reconciliarse, intercambiando la hostilidad por la paz en una relación rota. El mandato de Jesús en Mateo 5:24 prioriza la reconciliación horizontal antes que la adoración vertical: el ofensor debe buscar restaurar la relación. La forma pasiva o media sugiere intercambio mutuo y restauración relacional, no una disculpa unilateral sino reconciliación genuina que requiere ambas partes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65321, 'spa', 'Discutir o debatir con otros', 'Discutir o debatir con otros: discutir, debatir o razonar juntos con otros, implicando intercambio verbal y deliberacion colectiva. Los discipulos ''razonan entre si'' sobre no tener pan (Mt 16:7; Mr 8:16), y los principales sacerdotes deliberan como responder a la pregunta de Jesus sobre la autoridad de Juan (Mt 21:25; Mr 11:31; Lc 20:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65323, 'spa', 'Ponderar o reflexionar internamente', 'Ponderar o reflexionar internamente: ponderar, reflexionar o razonar dentro de uno mismo, actividad mental interior sin intercambio verbal. Maria ''consideraba en su mente'' que clase de saludo era este (Lc 1:29), los escribas ''razonaban en sus corazones'' sobre la autoridad de Jesus para perdonar pecados (Mr 2:6, 8), y la multitud ''se preguntaba en sus corazones'' si Juan seria el Cristo (Lc 3:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65331, 'spa', 'Pensamiento, razonamiento, deliberación — pensamientos interiores, razonamientos', 'Pensamiento, razonamiento, deliberación — pensamientos interiores, razonamientos o deliberaciones mentales, incluyendo dudas y opiniones que pueden permanecer sin expresar. Jesús lee los διαλογισμοί del corazón de los fariseos (Lc 5:22; 6:8), y a María se le dice que una espada traspasará su alma para que los pensamientos de muchos corazones sean revelados (Lc 2:35). Pablo declara que el Señor conoce que los razonamientos de los sabios son vanos (1 Co 3:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65333, 'spa', 'Disputa, argumento, controversia — una disputa abierta, argumento o controversia', 'Disputa, argumento, controversia — una disputa abierta, argumento o controversia entre personas, frecuentemente con contienda verbal o rivalidad competitiva. La discusión de los discípulos sobre quién era el mayor (Lc 9:46-47) es el caso más claro, donde Jesús percibe ''el διαλογισμός de su corazón'' — una clasificación interna que irrumpió en debate abierto. Filipenses 2:14 exhorta a hacer todo ''sin murmuraciones ni contiendas'', y 1 Ti 2:8 pide orar sin disputas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65340, 'spa', 'Dispersar o disolver', 'Dispersar o desbandar, provocando que un grupo unificado se disgregue y se disuelva. El ejemplo histórico de Gamaliel en Hechos 5:36 ilustra cómo el movimiento de Teudas se disolvió tras la muerte del líder: sus seguidores ''fueron dispersados'' (voz pasiva), disgregados sin organización. Las traducciones captan tanto la dispersión física como la disolución organizativa del movimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65341, 'spa', 'Testificar, dar testimonio solemne — testificar solemnemente o dar testimonio en', 'Testificar, dar testimonio solemne — testificar solemnemente o dar testimonio enfático de hechos, eventos o verdades, particularmente del mensaje del evangelio. Este es el uso principal lucano en Hechos: Pedro testifica en Pentecostés (Hch 2:40), Felipe y los apóstoles testifican en Samaria (Hch 8:25), Pablo testifica tanto a judíos como a griegos acerca del arrepentimiento y la fe (Hch 20:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65343, 'spa', 'Exhortar solemnemente, advertir con urgencia — exhortar, advertir o amonestar so', 'Exhortar solemnemente, advertir con urgencia — exhortar, advertir o amonestar solemnemente con grave urgencia, frecuentemente invocando a Dios como testigo. Este sentido aparece predominantemente en las Epístolas Pastorales: Pablo encarga a Timoteo ''delante de Dios y de Cristo Jesús y de los ángeles escogidos'' (1 Ti 5:21) y ''delante de Dios y de Cristo Jesús que juzgará a los vivos y a los muertos'' (2 Ti 4:1). La parábola lucana del hombre rico (Lc 16:28) también usa este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65352, 'spa', 'Contender vigorosamente', 'Contender o discutir con vehemencia, participando en una disputa o debate intenso. La actividad de los fariseos en Hechos 23:9 representa una argumentación feroz dentro del Sanedrín: «contendían» (imperfecto, sugiriendo una disputa prolongada), aparentemente a favor de Pablo respecto a la resurrección. La voz media puede enfatizar la implicación personal en el debate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65353, 'spa', 'Permanecer, persistir', 'Permanecer, continuar o persistir a través del tiempo — forma intensificada de μένω que subraya duración y constancia. Se aplica a personas que permanecen en un estado (Lc 1:22, Zacarías continuando mudo; Lc 22:28, los discípulos perseverando junto a Jesús en sus pruebas), a la permanencia de la verdad divina (Gá 2:5, el evangelio manteniéndose intacto), y a la inmutabilidad eterna de Dios contrastada con la decadencia de la creación (He 1:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65354, 'spa', 'Distribuir o repartir entre varios — se refiere al acto concreto de repartir o d', 'Distribuir o repartir entre varios — se refiere al acto concreto de repartir o distribuir algo entre múltiples receptores. Los soldados en el Gólgota ''repartieron sus vestiduras'' (Mt 27:35; Lc 23:34), y Jesús dijo a sus discípulos ''repartidlo entre vosotros'' en la Última Cena (Lc 22:17). Este es el uso más antiguo y común del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65355, 'spa', 'Estar dividido en contra — describe un estado interno de división, desunión o es', 'Estar dividido en contra — describe un estado interno de división, desunión o estar enfrentado unos contra otros. La enseñanza de Jesús de que ''todo reino dividido contra sí mismo es asolado'' (Lc 11:17) y la profecía de que los hogares se dividirán — tres contra dos, dos contra tres (Lc 12:52-53) — emplean este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65364, 'spa', 'División o disensión', 'División, disensión o separación: la ruptura de la unidad en partes opuestas. La pregunta tajante de Jesús en Lucas 12:51 indica que su mensaje inevitablemente genera «división» incluso dentro de las familias, al aceptarlo unos y rechazarlo otros. La traducción «división» capta tanto el acto de dividir como el estado resultante de discordia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65365, 'spa', 'Difundir o propagar', 'Esparcir o diseminar algo a lo largo de una población. La preocupación de los líderes judíos en Hechos 4:17 era que las noticias de la sanación y la enseñanza apostólica «no se difundieran más» entre el pueblo. El modo subjuntivo expresa propósito o temor: querían contener el mensaje e impedir su circulación más amplia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65366, 'spa', 'Hacer señas', 'Hacer señas o gestos como medio de comunicación no verbal. La condición de Zacarías tras su visión en el templo (Lucas 1:22) le obligó a usar gestos: «les hacía señas» (imperfecto, acción continua) para comunicar lo que no podía decir con palabras. Las traducciones reconocen unánimemente esta comunicación gestual compensatoria necesitada por su incapacidad de hablar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65367, 'spa', 'Pensamientos o intenciones', 'Pensamientos, razonamientos mentales o intenciones internas: el contenido de la actividad cognitiva. El conocimiento que Jesús tenía de los «pensamientos» de los fariseos (Lucas 11:17) demuestra una percepción divina del razonamiento no expresado y de las intenciones hostiles. El término enfatiza los procesos mentales internos más que las expresiones externas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65368, 'spa', 'Mente, entendimiento — la mente como facultad de comprensión y razonamiento mora', 'Mente, entendimiento — la mente como facultad de comprensión y razonamiento moral, particularmente en el contexto de la devoción total a Dios. Anclado en la cita del Shemá: ''con toda tu mente'' (Mt 22:37; Mr 12:30; Lc 10:27), donde διάνοια representa el compromiso intelectual requerido en el amor del pacto. También aparece en el entendimiento escatológico (1 Jn 5:20) y la promesa del nuevo pacto de la ley de Dios escrita en las mentes (He 8:10; 10:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65374, 'spa', 'Abrir, descubrir', 'Abrir completamente o poner al descubierto, usado para la apertura física (ojos, oídos, vientre) y la iluminación espiritual (mentes, Escrituras). Implica totalidad: no entreabrir, sino revelar plenamente. Pasajes clave: Marcos 7:34, donde Jesús ordena ''¡Efatá — sé abierto!''; Lucas 2:23, sobre el primogénito que abre el vientre; y los discípulos de Emaús cuyos ojos fueron abiertos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65381, 'spa', 'Pernoctar en actividad', 'Pasar la noche o permanecer durante las horas nocturnas, frecuentemente realizando alguna actividad sostenida. La práctica de Jesús antes de seleccionar a los apóstoles (Lucas 6:12) consistió en «pasar la noche en oración», no simplemente durmiendo sino orando activamente durante toda la noche. El participio sugiere actividad nocturna continua, enfatizando tanto la duración como el propósito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65382, 'spa', 'Completar un viaje', 'Completar o finalizar un viaje o trayecto, llevándolo a su conclusión prevista. El segmento marítimo del viaje de Pablo en Hechos 21:7 fue «completado» (participio aoristo) al llegar a Tolemaida, terminando así esa etapa del viaje. Las traducciones reconocen tanto la culminación del viaje como el sentido más amplio de concluir cualquier actividad prolongada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65383, 'spa', 'Cruzar, atravesar', 'Cruzar un cuerpo de agua o atravesar una región, generalmente en barca. Todas las apariciones sinópticas describen travesías en el mar de Galilea: Jesús cruza a su propia ciudad (Mt 9:1), los discípulos llegan a Genesaret tras la travesía (Mt 14:34; Mr 6:53), y las multitudes siguen a Jesús después de que cruza (Mr 5:21). El único uso metafórico en Lucas 16:26 describe el abismo infranqueable entre el seno de Abraham y el lugar de tormento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65387, 'spa', 'Travesía marítima', 'Navegar a través de un cuerpo de agua en barco, completando una travesía marítima. El viaje de Pablo hacia Roma incluyó «navegar a través» (Hechos 27:5) del mar abierto junto a la costa de Asia Menor, no navegación costera sino cruce de aguas abiertas. El participio aoristo marca la travesía completada antes de la siguiente etapa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65388, 'spa', 'Perturbación que provoca acción', 'Ambas apariciones en Hechos describen ser provocado a la acción por perturbación: los saduceos y autoridades del templo ''muy perturbados'' por la enseñanza de la resurrección (Hechos 4:2: español ''disgustados''), y Pablo ''muy irritado'' por la proclamación persistente de la joven esclava (Hechos 16:18: español ''indignándose''). La voz pasiva indica que algo externo ha agotado su paciencia y provocado una reacción fuerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65389, 'spa', 'Atravesar, pasar por', 'Viajar a través de un lugar o cruzar un territorio durante un viaje. El uso uniforme en las traducciones — español ''atravesar'', francés ''traverser'', alemán ''hindurchgehen'' — subraya que no se trata de un andar sin rumbo sino de un tránsito deliberado. Se usa para Jesús pasando por campos de grano en sábado (Lc 6:1), recorriendo pueblos camino a Jerusalén (Lc 13:22), y una multitud abriéndose paso (Lc 19:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65390, 'spa', 'Perplejidad profunda', 'Estar profundamente perplejo o totalmente desconcertado, expresando intenso desconcierto cognitivo ante sucesos inexplicables. El prefijo διά- intensifica la confusión más allá de la incertidumbre ordinaria. Herodes queda perplejo por informes sobre Jesús (Lc 9:7); la multitud de Pentecostés se halla estupefacta (Hch 2:12); los oficiales del templo no comprenden la fuga de los apóstoles (Hch 5:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65391, 'spa', 'Ganancia comercial', 'Obtener ganancia o beneficio mediante la actividad comercial y el intercambio mercantil. El noble que regresa en Lucas 19:15 pregunta a cada siervo «qué había ganado negociando» con el capital que les confió. El tiempo aoristo marca transacciones comerciales completadas. Todas las traducciones convergen en la obtención de beneficio comercial como significado central en este escenario económico parabólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65392, 'spa', 'Rabia homicida', 'Aparece exclusivamente en Hechos para describir rabia homicida provocada por el testimonio apostólico: el concilio siendo ''herido en el corazón'' y conspirando para matar a los apóstoles (Hechos 5:33), y la reacción furiosa de la multitud al discurso de Esteban (Hechos 7:54: español ''se enfurecían''). Ambos contextos involucran no mero desacuerdo sino rabia tan intensa que conduce inmediatamente a violencia o conspiración de violencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65393, 'spa', 'Saquear por la fuerza', 'Mateo 12:29 y Marcos 3:27 presentan la enseñanza de Jesús: «¿cómo puede alguien entrar en la casa del hombre fuerte y saquear sus bienes, si primero no le ata?». La doble aparición en Marcos enfatiza la secuencia: atar primero, saquear después. La imagen retrata la victoria de Cristo sobre el poder de Satanás, liberando a quienes estaban bajo su dominio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65394, 'spa', 'Rasgar, desgarrar', 'Rasgar o romper con fuerza, ya sean vestiduras, redes o cadenas. El sumo sacerdote rasgando sus vestiduras (Mt 26:65; Mc 14:63) ejemplifica el acto ritual de duelo e indignación. El término se extiende más allá de la ropa: una red reventando por los peces (Lc 5:6) y cadenas demoníacas destrozadas (Lc 8:29) demuestran su fuerza física bruta. Pablo y Bernabé repiten el gesto al ser venerados como dioses (Hch 14:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65395, 'spa', 'Explicar, aclarar', 'Ambas ocurrencias en Mateo involucran comunicación clarificadora: los discípulos pidiendo a Jesús que ''explique'' la parábola de la cizaña (Mateo 13:36: español ''Explícanos''), y los consiervos ''explicando'' claramente al amo lo que había hecho el siervo despiadado (Mateo 18:31: español ''declararon'', francés ''expliquer''). El verbo enfatiza hacer claros los asuntos oscuros o poco claros mediante explicación detallada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65396, 'spa', 'Extorsión por intimidación', 'Extorsionar dinero o bienes mediante intimidación, amenazas o coacción violenta contra las víctimas. La instrucción ética de Juan a los soldados (Lucas 3:14) prohíbe este abuso del poder militar: usar la posición y la fuerza para extraer dinero de los civiles. Se trata de explotación económica mediante coerción. Las traducciones reconocen el carácter coercitivo y amenazante de esta práctica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65397, 'spa', 'Dispersar, esparcir', 'Esparcir o dispersar personas, animales o grupos en múltiples direcciones, por juicio divino, persecución o circunstancia. Usado para las ovejas dispersadas al ser herido el pastor (Mateo 26:31; Marcos 14:27), Dios dispersando a los soberbios (Lucas 1:51) y los hijos de Dios que habían sido dispersados (Juan 11:52). El español emplea ''dispersar'' y ''esparcir''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65399, 'spa', 'Malgastar, derrochar', 'Malgastar o desperdiciar posesiones mediante gasto imprudente — extensión metafórica de la dispersión física. El hijo pródigo ''esparció'' sus bienes en vida disoluta (Lucas 15:13), y el administrador deshonesto fue acusado de ''malgastar'' la riqueza de su amo (Lucas 16:1). El cambio del español de ''dispersar'' a ''malgastar'' captura esta extensión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65404, 'spa', 'Despedazar, desgarrar violentamente', 'Aparece en contextos violentos de ser despedazado: el endemoniado que frecuentemente había ''sido despedazado'' por ataduras que rompía (Marcos 5:4: español ''fuera despedazado''), y el temor del tribuno romano de que Pablo fuera ''despedazado'' por la turba (Hechos 23:10: inglés ''torn apart'', francés ''déchirer''). Ambos enfatizan el despedazamiento o jalón violento y forzado por fuerzas opuestas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65405, 'spa', 'Dispersión providencial', 'Hechos 8:1 relata que «todos, salvo los apóstoles, fueron dispersados por Judea y Samaria» a causa de la persecución. Hechos 8:4 añade que «los que fueron dispersados iban predicando la palabra». Hechos 11:19 cuenta cómo los dispersados llegaron hasta Fenicia, Chipre y Antioquía. Lo que comenzó como persecución se transformó en expansión misionera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65406, 'spa', 'Diáspora judía', 'Juan 7:35 recoge la pregunta de los líderes judíos sobre si Jesús iría «a la Dispersión entre los griegos». Santiago 1:1 dirige su carta «a las doce tribus que están en la Dispersión». 1 Pedro 1:1 se dirige a «los expatriados de la Dispersión» en diversas provincias. El concepto abarca tanto la condición histórica del pueblo judío disperso como su significado teológico de testimonio entre las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65407, 'spa', 'Mandar, ordenar estrictamente', 'Dar una orden estricta o un mandato enfático, ordenando a alguien hacer o abstenerse de algo. En el NT, este uso en voz media porta una fuerte autoridad, de modo característico cuando Jesús ordena silencio sobre sus milagros e identidad (Mateo 16:20; Marcos 5:43; 7:36; 8:15; 9:9), patrón que los eruditos llaman el ''Secreto Mesiánico''. También aparece en instrucciones apostólicas (Hechos 15:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65411, 'spa', 'Intervalo temporal', 'Un intervalo o espacio de tiempo entre acontecimientos. La trágica secuencia de Hechos 5:7 se desarrolla cuando Safira entra «pasado un lapso de unas tres horas», sin saber de la muerte de su esposo. Este intervalo temporal intensifica el dramatismo, pues ella no tuvo oportunidad de enterarse de lo sucedido. Las traducciones reconocen este espacio medido entre dos eventos relacionados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65412, 'spa', 'Distinción o diferencia', 'En Romanos 3:22 y 10:12, Pablo enfatiza que «no hay distinción» entre judío y griego respecto al pecado y la salvación: todos son igualmente culpables y a todos se les ofrece la misma gracia en Cristo. En 1 Corintios 14:7, se usa una analogía musical: si la flauta o el arpa no producen notas distintas, nadie reconocerá la melodía. El término abarca tanto la ausencia de diferencia teológica como la necesidad de claridad comunicativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65413, 'spa', 'Pervertir, torcer, distorsionar', 'Torcer, pervertir o distorsionar — desviar a alguien o algo de lo recto o verdadero. Abarca el participio perfecto estativo que describe a toda una generación como moralmente ''perversa'' (Mt 17:17; Lc 9:41; Fil 2:15, en eco de Dt 32:5), y el sentido activo de corromper o desviar deliberadamente a otros (Lc 23:2, ''pervirtiendo a nuestra nación''; Hch 13:8, 10, Elimas intentando ''apartar'' al procónsul de la fe).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65420, 'spa', 'Rescatar, llevar a salvo', 'Llevar a salvo a través de un peligro físico, especialmente rescate de un naufragio o escolta peligrosa. Cuatro apariciones se concentran en Hechos: soldados que reciben orden de llevar a Pablo a salvo ante Félix (Hechos 23:24), y la dramática supervivencia del naufragio donde los 276 a bordo llegan vivos a tierra (Hechos 27:43-44; 28:1, 4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65422, 'spa', 'Salvar, preservar', 'Salvar o preservar a través del peligro en un sentido más amplio o espiritual. El centurión envía ancianos pidiendo que Jesús venga a ''salvar'' a su siervo (Lucas 7:3), la intervención de Pablo preserva a los pasajeros (Hechos 27:43), y la familia de Noé es ''llevada a salvo a través del agua'' en el arca (1 Pedro 3:20). Las traducciones reflejan la preservación divina a través del peligro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65423, 'spa', 'Sanar, curar', 'Sanar o curar de una enfermedad, restaurar a la plenitud física. En Mateo 14:36, todos los que tocaron el borde del manto de Jesús ''fueron completamente sanados''. El español distingue esta acepción con ''sanados'' en vez de ''salvados'', diferenciando la restauración médica del rescate, una pista diagnóstica de que la palabra griega aquí porta fuerza terapéutica más que soteriológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65427, 'spa', 'Ordenanza, disposición autoritativa', 'Aparece en dos contextos de ordenamiento autoritativo: la ley recibida por Israel ''por disposición de ángeles'' (Hechos 7:53: español ''disposición'', alemán ''Verordnung''), y las autoridades gobernantes como ''ordenanzas'' establecidas (Romanos 13:2: español ''disposiciones'', francés ''ordonnance''). Ambos enfatizan arreglos formales y vinculantes prescritos por autoridad legítima—ya sea mediación angélica u ordenamiento gubernamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65428, 'spa', 'Edicto oficial', 'Un edicto o decreto real que posee fuerza autoritativa. El mandato del faraón de matar a los niños hebreos fue un «edicto» formal (Heb 11:23) que los padres de Moisés desafiaron con valentía. El término enfatiza no cualquier orden, sino un decreto oficial y publicado respaldado por autoridad legal o real. Las traducciones convergen en un mandato formal y autoritativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65429, 'spa', 'Turbación profunda', 'Estar profundamente turbado o interiormente perturbado, experimentando perplejidad o agitación significativa. La reacción de María ante el saludo de Gabriel (Lucas 1:29) implicó no mera sorpresa, sino turbación profunda ante la aparición y las palabras del ángel. El aoristo pasivo sugiere el inicio súbito de ese estado. Las traducciones reconocen la intensidad de esta perturbación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65430, 'spa', 'Mandar, ordenar, dirigir', 'Mandar, ordenar, dirigir: mandar, ordenar o dar una directiva, instruyendo a alguien con autoridad sobre que hacer o como actuar. Este sentido principal (12 apariciones) abarca desde Jesus mandando que den de comer a la nina (Lc 8:55), siervos haciendo lo que se les ordeno (Lc 17:9-10), Moises recibiendo instrucciones sobre el tabernaculo (Hch 7:44), hasta Pablo dando directivas a las iglesias sobre las colectas (1 Co 16:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65434, 'spa', 'Designar, nombrar', 'Designar, nombrar: designar o nombrar a alguien o algo para un estatus, cargo o disposicion particular. Dos apariciones llevan este matiz institucional: Juan el Bautista diciendo a los recaudadores que no cobren mas de lo ''establecido'' para ellos (Lc 3:13), y Pablo declarando que la Ley fue ''ordenada'' por medio de angeles mediante un mediador (Ga 3:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65437, 'spa', 'Disponer, poner en orden', 'Disponer, poner en orden: disponer o poner las cosas en su debido orden, organizando los asuntos para que todo encaje en su lugar apropiado. Dos apariciones: Pablo promete ''poner en orden'' los asuntos restantes cuando llegue a Corinto (1 Co 11:34), y hace arreglos de viaje en Asos para la travesia (Hch 20:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65443, 'spa', 'Persistencia continuada', 'Continuar en un estado o persistir en una actividad a lo largo del tiempo. La observación de Pablo en Hechos 27:33 de que «continuáis esperando sin tomar alimento» subraya el ayuno sostenido durante la tormenta: habían persistido en ese estado de ansiedad sin comer. El tiempo presente enfatiza la continuación ininterrumpida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65444, 'spa', 'Guardar, atesorar fielmente', 'Dos usos distintos pero relacionados: María ''atesorando'' todas estas palabras en su corazón (Lucas 2:51: español ''guardaba'', alemán ''διετήρει''), preservándolas cuidadosamente, y la instrucción apostólica de ''guardarse'' de ciertas prácticas (Hechos 15:29: español ''guardándoos'', francés ''garder''). Ambos enfatizan preservación cuidadosa y fiel—ya sea de recuerdos preciosos o mandatos importantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65445, 'spa', 'Hacer o establecer pacto', 'Hacer, establecer o ratificar un pacto o testamento — el sentido técnico pactual usado en voz media para el acto solemne de establecer un pacto entre Dios y su pueblo. Cinco apariciones anclan este sentido: Dios declara ''haré (διαθήσομαι) un nuevo pacto con la casa de Israel'' (Heb 8:10; 10:16), Pedro invoca ''el pacto que Dios hizo (διέθετο) con vuestros padres'' (Hch 3:25), y Hebreos argumenta que donde hay testamento debe establecerse la muerte del testador (Heb 9:16-17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65447, 'spa', 'Asignar, disponer, otorgar', 'Asignar, disponer o legar algo a alguien — un sentido regio o testamentario de conferir autoridad, dominio o herencia. Las dos apariciones se hallan en Lucas 22:29, donde Jesús dice en la Última Cena: ''Yo dispongo (διατίθεμαι) para vosotros, como mi Padre dispuso (διέθετο) para mí, un reino.'' Aquí el verbo expresa el otorgamiento soberano de un rey que concede dominio a sus herederos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65450, 'spa', 'Permanecer, pasar tiempo', 'Quedarse, permanecer o pasar tiempo en un lugar, generalmente por un período prolongado. El sentido clásico de ''desgastar'' o ''consumir tiempo'' evolucionó completamente hacia un significado locativo en el NT. Las nueve apariciones se encuentran en Juan y Hechos: Jesús residiendo temporalmente en Judea (Juan 3:22), Pablo y Bernabé permaneciendo en diversas ciudades durante sus viajes misioneros (Hechos 14:3, 14:28, 15:35, 16:12, 20:6, 25:6, 25:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65456, 'spa', 'Alimento y sustento', 'Alimento y sustento, las provisiones básicas necesarias para la vida física. La instrucción de Pablo sobre el contentamiento (1 Tim 6:8) identifica el «alimento» (en plural: provisiones) y el abrigo como suficientes para una vida piadosa. El término enfatiza no el lujo, sino el sustento básico necesario para mantener la vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65457, 'spa', 'Amanecer, resplandecer', 'Dos aplicaciones notablemente diferentes de la misma idea raíz de brillar-a-través: el día escatológico ''amaneciendo'' con el lucero de la mañana (2 Pedro 1:19: español ''amanezca''), y la calle de oro de la Nueva Jerusalén siendo ''transparente'' como vidrio (Apocalipsis 21:21: español ''transparente'', alemán ''durchsichtig''). Ambos involucran luz pasando a través—ya sea alba a través de oscuridad o luz a través de material translúcido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65458, 'spa', 'Valer más, superar — valer más que algo, superar o aventajar en valor', 'Valer más, superar — valer más que algo, superar o aventajar en valor. Este es el sentido dominante del Nuevo Testamento, apareciendo en las comparaciones de Jesús sobre el valor humano frente a las aves (Mt 6:26; 10:31; Lc 12:7, 24) y frente a las ovejas (Mt 12:12). La fuerza retórica depende de la brecha entre lo que se compara: si Dios cuida de los gorriones, cuánto más de sus hijos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65460, 'spa', 'Importar, ser de interés — tener importancia o ser motivo de preocupación', 'Importar, ser de interés — tener importancia o ser motivo de preocupación. Gálatas 2:6 proporciona la única instancia neotestamentaria: ''lo que hayan sido no me importa — Dios no hace acepción de personas.'' Este sentido se desarrolla naturalmente del significado comparativo: si algo ''difiere'' lo suficiente como para merecer atención, entonces ''importa''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65461, 'spa', 'Llevar a través, difundir — el sentido literal y físico', 'Llevar a través, difundir — el sentido literal y físico: llevar o transportar de un lugar a otro, ser esparcido o arrastrado. En Marcos 11:16 Jesús prohíbe que alguien lleve objetos a través del templo; Hechos 13:49 describe la palabra del Señor siendo ''difundida'' por toda la región; Hechos 27:27 retrata un barco ''siendo llevado'' por el Adriático.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65465, 'spa', 'Diferir, ser diferente — diferir, ser distinto o variar respecto a otra cosa', 'Diferir, ser diferente — diferir, ser distinto o variar respecto a otra cosa. Pablo lo usa en 1 Corintios 15:41 — ''una estrella difiere de otra en gloria'' — y en Gálatas 4:1, donde un heredero que es niño ''en nada difiere'' del esclavo. El sentido es distinción cualitativa sin necesariamente implicar superioridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65469, 'spa', 'Escapar del peligro', 'Escapar o evadirse de un cautiverio o peligro, huyendo con éxito. En Hechos 27:42, el temor de los soldados era que los prisioneros escaparan durante el naufragio nadando hasta la orilla, lo cual constituía una falta capital para los guardias. El aoristo subjuntivo expresa la posibilidad de fuga que los soldados querían impedir mediante la ejecución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65470, 'spa', 'Difundir ampliamente', 'En Mateo 9:31, los dos ciegos sanados «difundieron la noticia de él por toda aquella región». Mateo 28:15 relata cómo los soldados «divulgaron» la historia fabricada sobre el robo del cuerpo de Jesús. Marcos 1:45 narra que el leproso sanado «salió y comenzó a divulgar el asunto» a pesar de la orden de Jesús. El verbo transmite una propagación espontánea e irreprimible de la noticia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65471, 'spa', 'Destruir, corromper, arruinar', 'Destruir por completo, corromper o causar deterioro, abarcando ruina física, corrupción moral y degeneración corporal. La voz pasiva en 2 Co 4:16 describe el gradual ''desgaste'' de la persona exterior, mientras que 1 Ti 6:5 lo aplica a mentes depravadas y moralmente arruinadas. En Apocalipsis, la voz activa retrata destrucción catastrófica: un tercio de las naves destruido (Ap 8:9) y la promesa escatológica de destruir a los destructores de la tierra (Ap 11:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65477, 'spa', 'Corrupción, descomposición', 'Descomposición física o putrefacción de un cuerpo muerto en la tumba, utilizado como término teológico en los argumentos sobre la resurrección. Pedro en Pentecostés cita el Salmo 16:10 para declarar que Dios no permitió que la carne de Jesús ''viera corrupción'' (Hch 2:27, 31), contrastando el cuerpo incorruptible de Cristo con los restos mortales de David. Pablo repite el argumento en Antioquía de Pisidia, distinguiendo al Cristo resucitado que ''no vio corrupción'' del David que sí la experimentó (Hch 13:34-37).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65479, 'spa', 'Diferente, diverso', 'Diferente, diverso o variado: describe cosas que difieren entre sí en tipo o carácter. En Ro 12:6 los dones espirituales son διάφορα (''diferentes'') según la gracia dada, y Hb 9:10 habla de diversas abluciones rituales. El énfasis recae en la distinción dentro de un conjunto, no en jerarquía de valor, sino en la variedad propia de los dones de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65480, 'spa', 'Guardar con esmero', 'Guardar cuidadosamente o proteger con diligencia, brindando vigilancia y preservación del daño. La cita del salmo en Lucas 4:10, dentro del relato de la tentación, promete que los ángeles te guardarán en todos tus caminos. El infinitivo expresa el propósito divino: Dios ordena a los ángeles proveer cuidado protector vigilante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65481, 'spa', 'Matar violentamente', 'Ambas instancias en Hechos se refieren a asesinato intentado o consumado: los líderes judíos que ''mataron'' a Jesús colgándolo en un madero (Hechos 5:30: español ''matasteis''), y los enemigos de Pablo tratando de ''matarlo'' en el templo (Hechos 26:21: francés ''mettre à mort''). La voz media enfatiza la naturaleza directa y personal de poner las manos sobre alguien para destruirlo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65482, 'spa', 'Separarse o partir', 'Separarse, partir o alejarse de alguien o algo. La sugerencia inoportuna de Pedro sobre construir enramadas (Lucas 9:33) surgió mientras Moisés y Elías se separaban de Jesús, los visitantes celestiales comenzando a alejarse de la escena terrenal. El infinitivo medio/pasivo expresa el movimiento de apartarse de la cercanía o compañía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65483, 'spa', 'Apto para enseñar', 'Aparece exclusivamente en las Epístolas Pastorales como cualificación de liderazgo: el obispo debe ser ''apto para enseñar'' (1 Timoteo 3:2), y el siervo del Señor no debe ser contencioso sino ''capaz de enseñar'' (2 Timoteo 2:24: español ''apto para enseñar,'' alemán ''lehrfaehig''). Ambos contextos enfatizan la aptitud de enseñanza como rasgo necesario de carácter para el liderazgo espiritual, no solo conocimiento sino la habilidad para instruir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65484, 'spa', 'Enseñado o instruido', 'Juan 6:45 cita Isaías 54:13: «Y todos serán enseñados por Dios»; esta enseñanza divina caracteriza a quienes vienen a Jesús. En 1 Corintios 2:13, Pablo contrasta «palabras enseñadas por la sabiduría humana» con verdades espirituales «enseñadas por el Espíritu». El pasaje de Juan apunta a la instrucción directa de Dios en el nuevo pacto, mientras que Pablo subraya el origen sobrenatural de la revelación apostólica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65485, 'spa', 'El acto, contenido o cuerpo de instrucción y doctrina autoritativa', 'El acto, contenido o cuerpo de instrucción y doctrina autoritativa. En los Sinópticos aparece en la reprensión de Jesús contra las tradiciones humanas elevadas al rango de enseñanza divina (Mt 15:9; Mr 7:7). Pablo lo emplea para la instrucción edificante que sostiene a la iglesia (Ro 12:7; 15:4) y para la sana doctrina a la que Timoteo debe aferrarse (1 Ti 4:13, 16; 2 Ti 3:16), en contraste con las enseñanzas engañosas de demonios (1 Ti 4:1). Abarca tanto la actividad de enseñar como el cuerpo doctrinal enseñado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65489, 'spa', 'Maestro, instructor', 'Maestro o instructor, especialmente quien ensena con autoridad en un contexto religioso o comunitario. Aplicado a Jesus como titulo de respeto equivalente a Rabbi (Mt 8:19; Mc 4:38; Jn 1:38; 3:2) y a figuras de autoridad en la iglesia primitiva: apostoles, profetas y maestros formando una triada fundacional (1 Co 12:28; Ef 4:11; Stg 3:1). El espanol ''maestro'' capta fielmente la connotacion autoritativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65493, 'spa', 'ensenar, instruir activamente', 'Ensenanza e instruccion activa: la transmision deliberada de conocimiento, doctrina o sabiduria practica a otros. Este sentido dominante abarca el ministerio publico de Jesus (Mt 4:23; 7:29), la ensenanza apostolica en las iglesias y toda actividad didactica general. El enfasis recae en la autoridad del maestro y en el contenido que comunica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65499, 'spa', 'ser ensenado, recibir instruccion', 'Recepcion pasiva de instruccion: ser ensenado o haber recibido ensenanza de parte de otro. La declaracion enfatica de Pablo de que su evangelio no le fue ensenado por ningun hombre sino por revelacion (Ga 1:12) ancla este sentido. Efesios 4:21 y 2 Tesalonicenses 2:15 recuerdan a los creyentes las doctrinas que ''les fueron ensenadas'', trasladando el foco del maestro al discipulo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65516, 'spa', 'Enseñanza, doctrina', 'Enseñanza, doctrina: Instrucción autoritativa o doctrina, que abarca tanto la actividad de enseñar como el cuerpo de contenido transmitido. Cuando se aplica a Jesús (Mt 7:28; Mr 1:27), destaca la autoridad impactante de su enseñanza en comparación con los escribas. En Hechos 2:42 designa uno de los cuatro pilares de la vida de la iglesia primitiva. Pablo advierte contra una διδαχή que se desvíe del modelo apostólico (Ro 16:17). La amplitud del término abarca tanto la doctrina sana como la errónea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65520, 'spa', 'Impuesto del templo', 'Ambas ocurrencias están en Mateo 17:24, donde los cobradores de impuestos se acercan a Pedro preguntando sobre Jesús pagando ''las dos dracmas'' (impuesto del templo). La referencia duplicada en un solo versículo enfatiza la cantidad específica en cuestión—el impuesto del templo de medio siclo que todo varón judío adulto debía pagar anualmente. El contexto establece la enseñanza de Jesús sobre que los hijos son libres de obligaciones del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65521, 'spa', 'Designación de Tomás', 'Usado exclusivamente como designación personal del apóstol Tomás en el Evangelio de Juan (11:16; 20:24; 21:2). La fórmula constante «Tomás, llamado Dídimo» muestra que el evangelista explica el nombre arameo para lectores de habla griega. Ambos nombres significan «gemelo», por lo que se trata de una traducción directa y no de un sobrenombre adicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65522, 'spa', 'dar, otorgar', 'El sentido activo central: dar, otorgar o entregar algo a alguien. Con 336 ocurrencias abarca la inmensa mayoría del uso: Dios dando autoridad (Mt 10:1), Jesús dando pan a los discípulos (Mt 14:19), un señor repartiendo talentos a sus siervos (Mt 25:15) y el acto sencillo de alcanzar una copa (Mt 26:27). Es el verbo primario de transferencia de posesión en el griego neotestamentario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65524, 'spa', 'ser dado, ser concedido', 'Voz pasiva: ser dado, ser concedido, ser otorgado. En 70 casos estas formas trasladan el foco gramatical al receptor y emplean frecuentemente la pasiva divina, donde Dios es el agente implícito. «A vosotros os es dado conocer los misterios» (Mt 13:11), «le fue dado hacer guerra» (Ap 13:7) y «toda buena dádiva viene de lo alto» (Stg 1:17). La pasiva revela la teología de la gracia como don recibido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65541, 'spa', 'poner, colocar', 'Extensión idiomática: poner, colocar o establecer algo en un lugar o estado. Aparece 7 veces, sobre todo en la fórmula del Nuevo Pacto «pondré mis leyes en sus mentes» (Heb 8:10; 10:16, citando Jer 31:33), y en la declaración de Pablo de que Dios «puso» en los apóstoles el ministerio de la reconciliación (2 Co 5:18-19). El verbo «dar» adquiere aquí valor locativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65565, 'spa', 'entregar, ceder', 'Entregar, rendir o ceder al poder o custodia de otro. Dos ocurrencias en Ap 20:13, donde «el mar entregó los muertos que había en él, y la Muerte y el Hades entregaron los muertos que había en ellos». El español «entregaron» selecciona vocabulario de cesión forzada, no de donación generosa. El contexto escatológico — la devolución de los muertos para el juicio final — marca esta acepción como rendición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65568, 'spa', 'producir, rendir fruto', 'Producir o rendir fruto, dicho de la tierra o las plantas que dan cosecha. Una sola ocurrencia clara en Mr 4:8, en la Parábola del Sembrador: la semilla cayó en buena tierra y «daba» (ἐδίδου) fruto, creciendo y multiplicándose. El español «daba» permite naturalmente esta extensión agrícola del verbo «dar», trasladando la transferencia de lo interpersonal a lo vegetal y productivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65583, 'spa', 'Despertar del sueño', 'Despertar o sacar a alguien del sueño físico. Se usa cuando Jesús es despertado durante la tormenta en el mar de Galilea (Mr 4:39; Lc 8:24). Los discípulos sacuden físicamente a Jesús para despertarlo, un acto urgente y corporal. El español ''lo despertaron'' refleja este significado directo de interrumpir el sueño de alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65584, 'spa', 'Avivar, agitar', 'Avivar, agitar o excitar en sentido figurado. Se aplica al mar sacudido por un fuerte viento (Jn 6:18, donde las olas son ''agitadas''), y al propósito de Pedro al escribir sus epístolas: avivar la mente de sus lectores hacia el pensamiento claro y el recuerdo (2 P 1:13; 3:1). El puente metafórico de ''despertar a una persona dormida'' a ''agitar el agua'' y ''avivar una mente'' es natural y expresivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65588, 'spa', 'Encrucijada o salida', 'Encrucijadas, vías principales o salidas de caminos: lugares donde los caminos se cruzan o salen de las ciudades, por donde pasa mucha gente. El rey de la parábola (Mateo 22:9) envía siervos a estas concurridas salidas de los caminos para encontrar invitados, ya que los convidados originales habían rechazado la invitación. El plural sugiere múltiples cruces e intersecciones transitadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65589, 'spa', 'Intérprete o traductor', 'Intérprete o traductor que vierte el habla de una lengua a otra, haciendo accesible el significado. La regulación de Pablo para el culto ordenado (1 Corintios 14:28) exige un intérprete para las lenguas, alguien capaz de traducir la expresión extática a un lenguaje inteligible para la congregación. Sin esta función mediadora, el habla solo beneficia al hablante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65590, 'spa', 'Interpretar, explicar', 'Interpretar o explicar el significado de algo, ya sean lenguas, profecía o Escritura. Este es el uso dominante (5 de 6 apariciones). Pablo insiste en que las lenguas en la asamblea deben ser interpretadas (1 Co 14:5, 13, 27), y en el camino de Emaús Jesús ''interpretó'' (διερμήνευσεν) toda la Escritura como apuntando hacia sí mismo (Lc 24:27). El español ''interpreta/intérprete'' refleja con precisión este acto de desentrañar significados ocultos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65592, 'spa', 'Traducir (un nombre)', 'Traducir una palabra o nombre de un idioma a otro. En Hechos 9:36, se dice que el nombre Tabita es ''traducido'' (διερμηνευομένη) como Dorcas, una conversión lingüística directa y no una explicación de un significado más profundo. El español ''traducida'' distingue esto limpiamente de la interpretación, aunque en griego el mismo verbo abarca ambos actos de salvar brechas de comprensión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65595, 'spa', 'Pasar a través de una región', 'Pasar a través de una región: El sentido primario y más frecuente: viajar o pasar a través de una región, ciudad o territorio, yendo de un lugar a otro. Es el significado estándar para los viajes itinerantes en los Evangelios y Hechos — Jesús pasando por ciudades (Lc 4:30; 9:6), un espíritu inmundo vagando «por lugares áridos» (Mt 12:43) o Pablo recorriendo Macedonia y Acaya (Hch 19:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65601, 'spa', 'Cruzar al otro lado', 'Cruzar al otro lado: Cruzar de un lado a otro, típicamente sobre agua o entre lugares distintos. En Marcos 4:35 Jesús dice «Pasemos al otro lado», y en Lucas 8:22 se narra el mismo cruce. El español «pasemos» y el inglés «Let us go across» resaltan el carácter decisivo de cruzar un límite. Este sentido también abarca pasajes donde el cruce es más figurado, un movimiento de una esfera a otra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65603, 'spa', 'Traspasar, atravesar', 'Traspasar, atravesar: Traspasar o penetrar algo físicamente, usado metafóricamente para una angustia emocional intensa. La única atestiguación es la profecía de Simeón a María en Lucas 2:35: «una espada atravesará tu propia alma». El español «atravesará» y el inglés «will pierce» conservan el movimiento violento de «a través» presente en la raíz. El griego clásico atestigua este sentido para armas y dolor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65606, 'spa', 'Difundirse por todas partes', 'Difundirse por todas partes: Difundirse o extenderse por una región; se usa para noticias, informes o fuerzas abstractas. En Lucas 5:15 la palabra describe cómo las noticias sobre Jesús «se extendían» cada vez más, y en Romanos 5:12 Pablo la emplea teológicamente: la muerte «pasó» a todos los hombres. El desplazamiento del recorrido físico a la difusión de información o realidad espiritual es una extensión metafórica natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65619, 'spa', 'Indagar minuciosamente', 'Investigar con esmero o hacer preguntas detalladas para obtener información. Los mensajeros de Cornelio en Hechos 10:17 habían ''indagado'' exhaustivamente para hallar la residencia de Simón, preguntando cuidadosamente hasta dar con la casa correcta. El participio aoristo indica una indagación completada con éxito: su interrogatorio metódico los condujo al lugar indicado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65620, 'spa', 'De dos años', 'De dos años de edad, describiendo la edad cronológica de niños pequeños. El decreto asesino de Herodes (Mat 2:16) apuntó a los varones ''de dos años para abajo'', calculando desde la aparición de la estrella a los magos. La forma genitiva especifica el rango de edad de las víctimas en este horrendo intento de eliminar al Rey recién nacido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65621, 'spa', 'Período de dos años', 'Ambas ocurrencias marcan períodos de dos años en el encarcelamiento de Pablo: Félix dejando a Pablo en cadenas por ''dos años'' hasta que Festo lo sucedió (Hechos 24:27: español ''dos años''), y los ''dos años'' de Pablo en su propia casa alquilada en Roma, recibiendo a todos los que venían (Hechos 28:30). El término funciona como simple notación cronológica marcando períodos extendidos pero delimitados del confinamiento de Pablo durante los cuales el ministerio nunca cesó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65622, 'spa', 'Narrar, relatar, contar', 'Exponer en detalle, narrar o dar un relato completo de sucesos a otros. El verbo implica una narración minuciosa y ordenada, no una mención breve. Testigos oculares ''narran'' lo que vieron en la sanación del endemoniado (Marcos 5:16), los Doce ''relatan'' sus experiencias de misión a Jesús (Lucas 9:10), y el hombre sanado recibe el encargo de ''describir'' las obras de Dios (Lucas 8:39). Hechos 8:33 lo usa para declarar el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65628, 'spa', 'Narración ordenada', 'Un relato o exposición ordenada, un recuento estructurado de eventos en secuencia. Lucas reconoce (1:1) que muchos ya habían intentado componer una ''narración'' de los acontecimientos evangélicos, lo cual contextualiza su propio relato cuidadosamente investigado. El término sugiere más que una crónica: una narración organizada y coherente con inicio, desarrollo y propósito definido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65629, 'spa', 'Perpetuo, para siempre', 'Perpetuo, continuo o incesante, usado exclusivamente en la frase formulaica εἰς τὸ διηνεκές (''a perpetuidad, para siempre'') para expresar duración ininterrumpida. En Hebreos porta un peso teológico decisivo: el sacerdocio de Melquisedec perdura sin fin (Hb 7:3); los sacrificios anuales no perfeccionan a los adoradores permanentemente (Hb 10:1); Cristo se sienta para siempre tras un solo sacrificio (Hb 10:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65630, 'spa', 'Confluencia de mares', 'Un lugar entre dos mares o donde dos cuerpos de agua confluyen, formando un banco de arena, arrecife o bajío. El sitio del naufragio en Hechos 27:41 era tal lugar: un ''sitio de dos mares'' donde las corrientes convergentes crearon un banco de arena en el cual la nave encalló y se partió, escenario del naufragio de Pablo en Malta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65631, 'spa', 'Penetrar completamente', 'La única aparición neotestamentaria (Heb 4:12) emplea este término metafóricamente para la palabra de Dios que ''penetra'' hasta la división del alma y el espíritu. Las glosas multilingües enfatizan la penetración y el traspaso, reflejando el sentido fundamental de atravesar algo por completo. El griego clásico lo usa para el traspaso físico con proyectiles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65632, 'spa', 'Separación o intervalo', 'El verbo abarca tanto la partida física como los intervalos temporales en las narraciones evangélicas. En Lucas 22:59 marca el lapso de una hora antes de otra acusación contra Pedro; en Lucas 24:51 describe a Jesús siendo llevado al cielo apartándose de los discípulos en la Ascensión; en Hechos 27:28 indica el espaciamiento entre sondeos de profundidad durante la tormenta. El término unifica separación espacial y distancia temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65633, 'spa', 'Insistir persistentemente', 'Ambas ocurrencias en Lucas-Hechos involucran insistencia persistente a pesar de la incredulidad inicial: la criada ''insistía'' que Pedro estaba con Jesús durante su negación (Lucas 22:59: español ''insistía''), y Rode ''insistía'' que Pedro estaba a la puerta mientras otros decían que estaba loca (Hechos 12:15). La voz media enfatiza su convicción personal y mantenimiento obstinado de su afirmación a pesar de la contradicción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65634, 'spa', 'Justo juicio divino', 'En Romanos 2:5, Pablo habla de la revelación del justo juicio de Dios en el día de la ira. El término combina justicia y juicio, subrayando la rectitud moral de los veredictos divinos. Las traducciones al español, francés y alemán preservan este doble énfasis en el acto judicial y su carácter justo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65635, 'spa', 'justo, recto (de personas)', 'Describe a una persona que vive de modo constante en conformidad moral con la voluntad de Dios y las normas eticas. El griego dikaios en este sentido personal abarca el territorio del hebreo tsaddiq: el fiel al pacto, aquel cuya vida concuerda con su profesion. En Mt 5:45, Dios envia lluvia sobre justos e injustos; en Mt 13:43, los justos resplandecen como el sol.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65639, 'spa', 'justo, equitativo (de acciones)', 'Aplicado a acciones, juicios o normas mas que a personas, senalando que son moralmente correctos o procedimentalmente equitativos. En Mt 20:4, el dueno de la vina promete ''lo que sea justo'' (dikaion), un salario equitativo. En Lc 12:57, Jesus desafia a la multitud a juzgar por si mismos ''lo que es justo''. El desplazamiento del caracter a la conducta es sutil pero consistente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65640, 'spa', 'el Justo (titulo)', 'Titulo mesianico y cristologico —''el Justo''— empleado exclusivamente en Hechos (3:14; 7:52; 22:14) como designacion propia de Jesus. El discurso de Esteban (Hch 7:52) acusa al Sanedrin de haber traicionado al ''Justo'', evocando la expectativa profetica. Aqui dikaios deja de ser un adjetivo general para funcionar como titulo nominal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65648, 'spa', 'justicia integral, sentido pleno', 'La justicia en toda su amplitud biblica: rectitud moral, fidelidad al pacto y, especialmente en Pablo, la accion salvifica por la cual Dios declara justos a los pecadores mediante la fe en Cristo (Ro 3:21-22; Fil 3:9). En el Sermon del Monte describe la vida etica que Dios exige y premia (Mt 5:6, 10, 20). En la teologia paulina se convierte en el concepto articulador de la salvacion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (65649, 'spa', 'ser declarado justo', 'ser declarado justo');